namespace Inventory;

/// <summary>
/// Coordinates cycle-count recording, discrepancy reconciliation and valuation updates.
/// </summary>
public sealed class CycleCountService
{
    private readonly CycleCountBook _countBook = new();
    private readonly DiscrepancyLog _discrepancyLog = new();

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _countBook.RecordCount(item, warehouse, counted);

    public int CountVariance(StockItem item) =>
        _countBook.CountVariance(item);

    public string Reconcile(StockItem item) =>
        _discrepancyLog.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancyLog.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _countBook.UpdateValuation(item, unitCost);
}

/// <summary>
/// Stores recorded counts and performs count and valuation calculations.
/// </summary>
internal sealed class CycleCountBook
{
    private const int MaximumVariance = 1000;
    private const decimal MaximumValuation = 1_000_000m;

    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public string RecordCount(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";

        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";

        _valuations[item.Sku] = variance * (variance > 0 ? 2.0m : 1.0m);
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";

        return "recorded";
    }

    public int CountVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;

        var variance = counted - item.OnHand;
        if (variance > MaximumVariance)
            return MaximumVariance;
        if (variance < -MaximumVariance)
            return -MaximumVariance;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;

        return variance;
    }

    public decimal UpdateValuation(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku) || unitCost < 0m)
            return 0m;

        var basisQuantity = item.OnHand > 0 ? item.OnHand : 0;
        var value = Math.Min(basisQuantity * unitCost, MaximumValuation);
        _valuations[item.Sku] = value;

        return basisQuantity == 0 || unitCost == 0m ? 0m : value;
    }
}

/// <summary>
/// Classifies and stores inventory discrepancies.
/// </summary>
internal sealed class DiscrepancyLog
{
    private const int ReconciliationLimit = 1000;
    private const int FlagLimit = 5000;
    private const int MaximumReasonLength = 200;

    private readonly List<string> _entries = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        var available = item.OnHand - item.Reserved;
        if (available < 0)
            return AddAndReturn(item.Sku, "oversold", "oversold");
        if (item.Reserved < 0)
            return AddAndReturn(item.Sku, "negative-reserve", "bad reserve");
        if (item.OnHand == 0 && item.Reserved > 0)
            return AddAndReturn(item.Sku, "phantom-reserve", "phantom");

        if (available > 0 && available < 5)
            _entries.Add($"{item.Sku}:low");
        else if (available > 10000)
            _entries.Add($"{item.Sku}:excess");

        return _entries.Count > ReconciliationLimit
            ? "too many discrepancies"
            : "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku) || string.IsNullOrEmpty(reason))
            return false;

        if (reason.Length > MaximumReasonLength)
            reason = reason.Substring(0, MaximumReasonLength);
        if (_entries.Count > FlagLimit)
            return false;

        var tag = Classify(reason);
        _entries.Add($"{item.Sku}:{tag}:{reason}");
        return tag != "note";
    }

    private string AddAndReturn(string sku, string discrepancy, string result)
    {
        _entries.Add($"{sku}:{discrepancy}");
        return result;
    }

    private static string Classify(string reason)
    {
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            return "critical";
        if (reason.StartsWith("low", StringComparison.Ordinal))
            return "warn";
        if (reason.StartsWith("excess", StringComparison.Ordinal))
            return "info";
        return "note";
    }
}
